import numpy as np
import random

def apply_rules(G):
    N = G.shape[0]
    G_next = G.copy()

    # Iterate over all 7x7 possible top-left corners of a 2x2 block
    for i in range(N - 1):
        for j in range(N - 1):
            block = [
                G[i, j], G[i+1, j], G[i, j+1], G[i+1, j+1]
            ]
            S = sum(block)

            # Cells in the 2x2 block
            coords = [(i, j), (i+1, j), (i, j+1), (i+1, j+1)]

            if S == 3:
                # Rule 1: The last sterile section gets infected.
                sterile_coords = []
                for k, (r, c) in enumerate(coords):
                    if G[r, c] == 0:
                        sterile_coords.append((r, c))

                # Assuming "the last sterile section" means the one found last in the standard iteration order
                # Or, more robustly, we apply the infection if there is exactly one sterile section (which must be true if S=3)
                if len(sterile_coords) == 1:
                    r, c = sterile_coords[0]
                    G_next[r, c] = 1

            elif S == 2:
                # Rule 2: Mutation (all 4 cells flip state)
                for r, c in coords:
                    G_next[r, c] = 1 - G[r, c]

    return G_next

def simulate(initial_config, steps=500):
    G = np.array(initial_config, dtype=int)

    history = []
    for t in range(steps):
        G_next = apply_rules(G)
        # Check for stabilization or cycle detection
        if np.array_equal(G_next, G):
            # Stabilized
            return "STABLE", G

        # Simple check for saturation (full infection)
        if np.sum(G_next) == 8*8:
            return "FULL", G_next

        G = G_next

    # If no immediate stabilization or full infection, check for recent repetition
    # Simple cycle detection (omitted for brevity in initial check, relying on large steps)
    return "SPREADING", G

def generate_compact(k, N):
    # Creates a compact square/near-square block centered roughly
    size = int(np.ceil(np.sqrt(k)))
    grid = np.zeros((N, N), dtype=int)

    offset = (N - size) // 2
    for r in range(size):
        for c in range(size):
            grid[offset + r, offset + c] = 1

    # Adjust size if k is not a perfect square and pad with random cells to reach k
    count = np.sum(grid)
    if count < k:
        cells_needed = k - count
        coords = [(r, c) for r in range(N) for c in range(N) if grid[r, c] == 0]
        random.shuffle(coords)
        for i in range(min(cells_needed, len(coords))):
            r, c = coords[i]
            grid[r, c] = 1

    return grid.tolist()

def generate_random(k, N):
    grid = np.zeros((N, N), dtype=int)
    coords = [(r, c) for r in range(N) for c in range(N)]
    random.shuffle(coords)

    for i in range(k):
        r, c = coords[i]
        grid[r, c] = 1

